import React, { useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';

const Navbar = () => {
  const { t, i18n } = useTranslation();
  const { user, logout, isAuthenticated } = useAuth();
  const { isDarkMode, toggleTheme } = useTheme();
  const location = useLocation();
  const navigate = useNavigate();
  const [showUserMenu, setShowUserMenu] = useState(false);
  const [showMobileMenu, setShowMobileMenu] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/home');
  };

  const changeLanguage = (lng) => {
    i18n.changeLanguage(lng);
    localStorage.setItem('language', lng);
  };

  const isActive = (path) => location.pathname === path;

  return (
    <nav className="navbar">
      <div className="navbar-content">
        <Link to="/dashboard" className="navbar-brand">
          Smart Health
        </Link>

        <ul className="navbar-nav">
          <li>
            <Link 
              to="/dashboard" 
              className={isActive('/dashboard') ? 'active' : ''}
            >
              {t('navigation.dashboard')}
            </Link>
          </li>
          
          {user?.role === 'doctor' && (
            <li>
              <Link 
                to="/health-form" 
                className={isActive('/health-form') ? 'active' : ''}
              >
                {t('navigation.healthForm')}
              </Link>
            </li>
          )}
          
          <li>
            <Link 
              to="/queue" 
              className={isActive('/queue') ? 'active' : ''}
            >
              {t('navigation.queue')}
            </Link>
          </li>
          
          <li>
            <Link 
              to="/reports" 
              className={isActive('/reports') ? 'active' : ''}
            >
              {t('navigation.reports')}
            </Link>
          </li>
          
          <li>
            <Link 
              to="/healthcare-map" 
              className={isActive('/healthcare-map') ? 'active' : ''}
            >
              {t('navigation.map')}
            </Link>
          </li>
        </ul>

        <div className="user-menu">
          <button 
            className="user-menu-toggle"
            onClick={() => setShowUserMenu(!showUserMenu)}
          >
            {user?.name} ▼
          </button>
          
          {showUserMenu && (
            <div className="user-menu-dropdown">
              <Link 
                to="/settings" 
                onClick={() => setShowUserMenu(false)}
              >
                {t('navigation.settings')}
              </Link>
              
              <div style={{ padding: '0.75rem 1rem', borderBottom: '1px solid #eee' }}>
                <strong>Language:</strong>
                <div style={{ marginTop: '0.5rem' }}>
                  <button 
                    onClick={() => changeLanguage('en')}
                    style={{ 
                      marginRight: '0.5rem', 
                      background: i18n.language === 'en' ? '#007bff' : 'transparent',
                      color: i18n.language === 'en' ? 'white' : '#333',
                      border: '1px solid #007bff',
                      padding: '0.25rem 0.5rem',
                      borderRadius: '3px',
                      cursor: 'pointer'
                    }}
                  >
                    EN
                  </button>
                  <button 
                    onClick={() => changeLanguage('hi')}
                    style={{ 
                      marginRight: '0.5rem', 
                      background: i18n.language === 'hi' ? '#007bff' : 'transparent',
                      color: i18n.language === 'hi' ? 'white' : '#333',
                      border: '1px solid #007bff',
                      padding: '0.25rem 0.5rem',
                      borderRadius: '3px',
                      cursor: 'pointer'
                    }}
                  >
                    हिं
                  </button>
                  <button 
                    onClick={() => changeLanguage('mr')}
                    style={{ 
                      background: i18n.language === 'mr' ? '#007bff' : 'transparent',
                      color: i18n.language === 'mr' ? 'white' : '#333',
                      border: '1px solid #007bff',
                      padding: '0.25rem 0.5rem',
                      borderRadius: '3px',
                      cursor: 'pointer'
                    }}
                  >
                    मर
                  </button>
                </div>
              </div>
              
              <button onClick={handleLogout}>
                {t('auth.logout')}
              </button>
            </div>
          )}
        </div>

        <button 
          className="mobile-menu-toggle"
          onClick={() => setShowMobileMenu(!showMobileMenu)}
        >
          ☰
        </button>
      </div>
    </nav>
  );
};

export default Navbar;
